package core

import (
	"context"
	"fmt"
	"strings"

	"github.com/charmbracelet/log"
	clablinks "github.com/srl-labs/containerlab/links"
	clabutils "github.com/srl-labs/containerlab/utils"
)

// bridgeNSMigParentNode resolves the namespace host of a migrated bridge-side
// endpoint. Stale refs carry either a live bridge node (resolved via the
// topology) or the name-encoded <bridge>|<parent> form of a node that is
// already removed from the desired topology.
func (c *CLab) bridgeNSMigParentNode(ref applyEndpointRef) (clablinks.Node, error) {
	if parentNode, err := c.bridgeNSParentNode(ref.key.node); err == nil {
		return parentNode, nil
	}
	parts := strings.SplitN(ref.key.node, "|", 2)
	if len(parts) != 2 {
		return nil, fmt.Errorf("cannot resolve namespace host of bridge %q", ref.key.node)
	}
	node, exists := c.Nodes[parts[1]]
	if !exists {
		return nil, fmt.Errorf(
			"bridge %q: parent container %q not found",
			ref.key.node,
			parts[1],
		)
	}
	return node, nil
}

// parkMigratedBridgeNSPorts parks bridge-side veth ends whose owning in-container
// bridge was replaced by a bridge under a different parent (the move case).
// The veth pair stays intact: only the parked half leaves the dying parent's
// namespace, so the client-side end keeps its state untouched.
func (c *CLab) parkMigratedBridgeNSPorts(
	ctx context.Context,
	plan *applyPlan,
) error {
	if plan == nil || len(plan.bridgeNSMigrations) == 0 {
		return nil
	}

	for i := range plan.bridgeNSMigrations {
		mig := &plan.bridgeNSMigrations[i]

		if mig.relocation != nil {
			continue
		}

		// The old bridge node may already be deleted from the desired topology
		// (the move case); resolve its namespace host by the name-encoded
		// parent suffix, falling back to the normal resolution.
		parentNode, err := c.bridgeNSMigParentNode(mig.staleRef)
		if err != nil {
			return err
		}

		newNode, exists := c.Nodes[mig.newKey.node]
		if !exists {
			return fmt.Errorf("bridge migration target %q not found", mig.newKey.node)
		}
		longName := newNode.Config().LongName

		relocation, err := clablinks.ParkBridgePortByOwnership(
			ctx,
			parentNode,
			mig.staleRef.key.node,
			mig.staleRef.key.iface,
			longName,
		)
		if err != nil {
			return err
		}

		mig.relocation = relocation
	}

	return nil
}

// restoreMigratedBridgeNSPorts moves parked bridge-side ends into the replacement
// bridge's parent namespace after that container (and the bridge) exist again,
// relabels the ownership altname to the replacement bridge node, and re-enslaves
// the port to the bridge. The corresponding live link is marked full-deployed so
// deployLinks skips pair re-creation for it.
func (c *CLab) restoreMigratedBridgeNSPorts(
	ctx context.Context,
	plan *applyPlan,
) error {
	if plan == nil || len(plan.bridgeNSMigrations) == 0 {
		return nil
	}

	for i := range plan.bridgeNSMigrations {
		mig := &plan.bridgeNSMigrations[i]

		if mig.relocation == nil || plan.plannedLinkSet == nil {
			continue
		}

		// Restore into the replacement bridge's parent namespace; the bridge
		// node interfaces with the parent's ns through its GetNSPath override.
		bridgeNode, exists := c.Nodes[mig.newKey.node]
		if !exists {
			return fmt.Errorf("bridge migration target %q not found", mig.newKey.node)
		}

		if err := mig.relocation.RestoreBridgePort(
			ctx,
			bridgeNode,
			mig.newKey.node,
			bridgeNSNameInNamespace(mig.newKey.node),
			clabutils.SanitizeInterfaceName(mig.newKey.iface),
		); err != nil {
			return err
		}

		// The migrated pair is complete end-to-end (the client-side end was
		// never touched and the parked bridge-side half is restored and
		// enslaved). Filter the corresponding replaced link out of addedLinks
		// so endpoint removal and pair re-creation never touch it.
		kept := plan.addedLinks[:0]
		for _, link := range plan.addedLinks {
			if clablinks.RuntimeEndpointsContainEndpoint(
				link,
				mig.newKey.node,
				mig.newKey.iface,
			) {
				log.Info(
					"Restored migrated bridge port into replacement bridge",
					"bridge",
					mig.newKey.node,
					"port",
					mig.newKey.iface,
				)
				continue
			}
			kept = append(kept, link)
		}
		plan.addedLinks = kept
	}

	return nil
}

package core

import (
	"context"
	"fmt"
	"sort"
	"strings"

	clabconstants "github.com/srl-labs/containerlab/constants"
	clablabruntime "github.com/srl-labs/containerlab/labruntime"
	clabruntime "github.com/srl-labs/containerlab/runtime"
	clabutils "github.com/srl-labs/containerlab/utils"
)

type runtimeNodeGroup struct {
	name               string
	containers         []clabruntime.GenericContainer
	distributed        bool
	external           bool
	rootNamespaceBased bool
}

func (c *CLab) runtimeNodeGroups(
	ctx context.Context,
) (map[string]*runtimeNodeGroup, error) {
	containers, err := c.ListContainers(ctx, WithListLabName(c.Config.Name))
	if err != nil {
		return nil, err
	}

	result := make(map[string]*runtimeNodeGroup)
	var duplicates []string

	for _, ctr := range containers {
		if ctr.Labels[clabconstants.ToolType] != "" {
			continue
		}

		nodeName := ctr.Labels[clabconstants.NodeName]
		if nodeName == "" {
			continue
		}

		groupName := ctr.Labels[clabconstants.RootNodeName]
		distributed := groupName != ""
		if groupName == "" {
			groupName = nodeName
		}

		group, exists := result[groupName]
		if !exists {
			group = &runtimeNodeGroup{
				name:        groupName,
				distributed: distributed,
			}
			result[groupName] = group
		}
		group.containers = append(group.containers, ctr)
		group.distributed = group.distributed || distributed

		if !group.distributed && len(group.containers) > 1 {
			duplicates = append(duplicates, nodeName)
			continue
		}
	}

	// Pre-existing resources have no containerlab labels, but still participate in apply.
	for nodeName, node := range c.Nodes {
		cfg := node.Config()
		if cfg == nil {
			continue
		}
		if _, exists := result[nodeName]; exists {
			continue
		}
		if cfg.IsRootNamespaceBased {
			result[nodeName] = &runtimeNodeGroup{
				name:               nodeName,
				rootNamespaceBased: true,
			}
			continue
		}
		// BridgeNS bridges (in-container bridges) don't have their own containers,
		// but they do represent real resources. Check if parent container exists.
		//
		// Trade-off: We only check parent container existence, not the actual bridge
		// interface inside the parent. This is fast and simple, but may show the bridge
		// as "current" when the bridge interface is missing (e.g., after container
		// recreation). The detailed bridge existence check is handled during
		// reconciliation by linkIntact() and bridgeMasterMismatch().
		if cfg.Kind == "bridge" && cfg.NetworkMode != "" && cfg.NetworkMode != "host" {
			if parentName, err := clabutils.ContainerNameFromNetworkMode(
				cfg.NetworkMode,
			); err == nil {
				if _, parentExists := result[parentName]; parentExists {
					result[nodeName] = &runtimeNodeGroup{
						name:               nodeName,
						rootNamespaceBased: true,
					}
				}
			}
			continue
		}
		if !cfg.SkipUniquenessCheck || node.GetContainerStatus(ctx) == clabruntime.NotFound {
			continue
		}
		result[nodeName] = &runtimeNodeGroup{name: nodeName, external: true}
	}

	if len(duplicates) > 0 {
		sort.Strings(duplicates)
		return nil, fmt.Errorf(
			"apply supports only single-container nodes, found multiple containers for nodes: %s",
			strings.Join(duplicates, ", "),
		)
	}

	for _, group := range result {
		sort.Slice(group.containers, func(i, j int) bool {
			return runtimeContainerLess(group.containers[i], group.containers[j])
		})
	}

	return result, nil
}

// NeedsInitialDeploy reports whether the lab has no runtime state yet, i.e. whether
// Deploy would perform a fresh deployment instead of reconciling a running lab.
func (c *CLab) NeedsInitialDeploy(ctx context.Context) (bool, error) {
	if c.LabRuntime != nil {
		checker, ok := c.LabRuntime.(clablabruntime.LabExistenceChecker)
		if !ok {
			return false, fmt.Errorf(
				"lab runtime %q cannot determine whether the lab already exists",
				c.globalRuntimeName,
			)
		}
		exists, err := checker.LabExists(ctx, clablabruntime.InspectRequest{
			Name:     c.Config.Name,
			Identity: c.labRuntimeIdentity,
		})

		return !exists, err
	}

	currentNodes, err := c.runtimeNodeGroups(ctx)
	if err != nil {
		return false, err
	}

	return c.needsInitialDeploy(currentNodes)
}

func (c *CLab) needsInitialDeploy(currentNodes map[string]*runtimeNodeGroup) (bool, error) {
	if len(currentNodes) == 0 {
		return true, nil
	}
	for _, node := range currentNodes {
		if !node.external && !node.rootNamespaceBased {
			return false, nil
		}
	}

	state, err := c.LoadState()
	return state == nil, err
}

func (c *CLab) setMgmtBridgeFromRuntime(
	currentNodes map[string]*runtimeNodeGroup,
) error {
	if c.Config.Mgmt.Bridge != "" {
		return nil
	}

	var bridge string
	for _, runtimeNode := range currentNodes {
		for _, ctr := range runtimeNode.containers {
			// only containers attached to the default management network, or
			// without a runtime network, carry the default network's bridge
			// label. Unknown networks, e.g. ones dropped from the mgmt list,
			// must not contribute their bridge.
			switch ctr.NetworkName {
			case "", c.Config.Mgmt.Network:
			default:
				continue
			}
			ctrBridge := ctr.Labels[clabconstants.NodeMgmtNetBr]
			if ctrBridge == "" {
				continue
			}
			if bridge == "" {
				bridge = ctrBridge
				continue
			}
			if bridge != ctrBridge {
				return fmt.Errorf(
					"runtime lab has conflicting management bridge labels: %q and %q",
					bridge,
					ctrBridge,
				)
			}
		}
	}

	if bridge != "" {
		c.Config.Mgmt.Bridge = bridge
	}

	return nil
}

func (c *CLab) updateRuntimeInfoForExistingNodes(ctx context.Context) error {
	for _, nodeName := range sortedNodeNames(c.Nodes) {
		node := c.Nodes[nodeName]
		if node.GetContainerStatus(ctx) == clabruntime.NotFound {
			continue
		}
		if err := node.UpdateConfigWithRuntimeInfo(ctx); err != nil {
			return fmt.Errorf("failed to update runtime info for node %q: %w", nodeName, err)
		}
	}

	return nil
}

func sortedRuntimeNodeGroupNames(nodes map[string]*runtimeNodeGroup) []string {
	names := make([]string, 0, len(nodes))
	for name := range nodes {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

func runtimeContainerNodeName(ctr clabruntime.GenericContainer) string {
	if name := ctr.Labels[clabconstants.NodeName]; name != "" {
		return name
	}
	if len(ctr.Names) > 0 {
		return ctr.Names[0]
	}
	return ctr.ID
}

func runtimeContainerLess(a, b clabruntime.GenericContainer) bool {
	// internal holders own the network namespace of the other containers in the group,
	// so they sort first to be deleted last.
	aInternal := a.Labels[clabconstants.InternalNode] == "true"
	bInternal := b.Labels[clabconstants.InternalNode] == "true"
	if aInternal != bInternal {
		return aInternal
	}

	aName := runtimeContainerNodeName(a)
	bName := runtimeContainerNodeName(b)

	aOrder := runtimeComponentSortOrder(aName)
	bOrder := runtimeComponentSortOrder(bName)
	if aOrder != bOrder {
		return aOrder < bOrder
	}

	return aName < bName
}

func runtimeComponentSortOrder(name string) int {
	idx := strings.LastIndex(name, "-")
	if idx < 0 || idx == len(name)-1 {
		return 0
	}

	slot := strings.ToUpper(name[idx+1:])
	if len(slot) == 1 && slot[0] >= 'A' && slot[0] <= 'Z' {
		return 100 - int(slot[0])
	}

	var n int
	for _, r := range slot {
		if r < '0' || r > '9' {
			return 0
		}
		n = n*10 + int(r-'0')
	}

	return n
}

package core

import (
	"context"
	"fmt"
	"net/netip"

	clabtypes "github.com/srl-labs/containerlab/types"

	clablinks "github.com/srl-labs/containerlab/links"
)

// ApplyResult summarizes the changes applied by an apply operation.
type ApplyResult struct {
	DryRun           bool     `json:"dry-run"`
	DeployedLab      bool     `json:"deployed-lab"`
	LabName          string   `json:"lab-name,omitempty"`
	AddedNodes       []string `json:"added-nodes"`
	DeletedNodes     []string `json:"deleted-nodes"`
	RecreatedNodes   []string `json:"recreated-nodes"`
	StartedNodes     []string `json:"started-nodes"`
	AddedLinks       []string `json:"added-links"`
	DeletedEndpoints []string `json:"deleted-endpoints"`
	RestartedNodes   []string `json:"restarted-nodes"`
	// NodeChangeReasons explains per node why apply restarts or recreates it,
	// e.g. "added link" or "config drift: image".
	NodeChangeReasons map[string]string `json:"node-change-reasons,omitempty"`
}

func applyResultFromPlan(plan *applyPlan) *ApplyResult {
	result := &ApplyResult{
		AddedNodes:        []string{},
		DeletedNodes:      []string{},
		RecreatedNodes:    []string{},
		StartedNodes:      []string{},
		AddedLinks:        []string{},
		DeletedEndpoints:  []string{},
		RestartedNodes:    []string{},
		NodeChangeReasons: map[string]string{},
	}
	if plan == nil {
		return result
	}

	result.AddedNodes = sortedStringSet(plan.addedNodeSet)
	result.DeletedNodes = sortedStringSet(plan.deletedNodeSet)
	result.RecreatedNodes = sortedStringSet(plan.recreatedNodeSet)
	result.StartedNodes = sortedStringSet(plan.startNodeSet)
	result.AddedLinks = applyLinkNames(plan.addedLinks)
	result.DeletedEndpoints = applyDeletedEndpointNames(plan.staleEndpoints)
	result.RestartedNodes = sortedStringSet(unionStringSets(
		plan.restartNodeSet,
		plan.linkRestartNodeSet,
	))

	for nodeName, reason := range plan.nodeChangeReasons {
		result.NodeChangeReasons[nodeName] = reason
	}

	return result
}

// Apply deploys a lab if it is absent, otherwise it aligns the deployed lab with the
// desired topology using runtime state as baseline.
func (c *CLab) Apply(
	ctx context.Context,
	options *ApplyOptions,
) (*ApplyResult, error) {
	if options == nil {
		var err error
		options, err = NewApplyOptions(0)
		if err != nil {
			return nil, err
		}
	}

	if c.Config.Name == "" {
		return nil, fmt.Errorf("missing lab name")
	}
	if !c.TopoPaths.TopologyFileIsSet() {
		return nil, fmt.Errorf(
			"apply requires a topology file; provide --topo when it cannot be derived from --name",
		)
	}

	currentNodes, err := c.runtimeNodeGroups(ctx)
	if err != nil {
		return nil, err
	}

	return c.apply(ctx, options, currentNodes)
}

func (c *CLab) apply(
	ctx context.Context,
	options *ApplyOptions,
	currentNodes map[string]*runtimeNodeGroup,
) (*ApplyResult, error) {
	initialDeploy, err := c.needsInitialDeploy(currentNodes)
	if err != nil {
		return nil, err
	}
	if initialDeploy {
		result := &ApplyResult{
			DryRun:      options.dryRun,
			DeployedLab: true,
			LabName:     c.Config.Name,
		}

		if options.dryRun {
			return result, nil
		}

		deployOptions, err := NewDeployOptions(options.maxWorkers)
		if err != nil {
			return nil, err
		}
		deployOptions.SetSkipPostDeploy(options.skipPostDeploy).
			SetSkipLabDirFileACLs(options.skipLabDirFileACLs).
			SetGraph(options.graph).
			SetExportTemplate(options.exportTemplate)

		if _, err := c.deploy(ctx, deployOptions); err != nil {
			return nil, err
		}

		return result, nil
	}

	if err := c.setMgmtBridgeFromRuntime(currentNodes); err != nil {
		return nil, err
	}

	if err := c.resolveMgmtNetLinkNetworks(ctx); err != nil {
		return nil, err
	}

	if err := c.setMgmtNetLinkBridges(); err != nil {
		return nil, err
	}

	if err := c.ResolveLinks(); err != nil {
		return nil, err
	}

	if err := c.checkApplyTopologyDefinition(ctx); err != nil {
		return nil, err
	}

	plan, err := c.planApply(ctx, currentNodes)
	if err != nil {
		return nil, err
	}

	if options.dryRun {
		result := applyResultFromPlan(plan)
		result.DryRun = true
		return result, nil
	}

	if err := c.reconcileNodes(ctx, plan); err != nil {
		return nil, err
	}

	if plan.empty() {
		if c.tailscaleProxyEnabled() {
			if err := c.updateRuntimeInfoForExistingNodes(ctx); err != nil {
				return nil, err
			}
		}
		if err := c.syncTailscaleProxy(ctx); err != nil {
			return nil, err
		}
		if options.finalizeNoop {
			if err := c.prepareApply(
				ctx,
				nil,
				options.skipLabDirFileACLs,
				currentNodes,
			); err != nil {
				return nil, err
			}
		}
		if err := c.SyncMgmtHostRoutes(ctx); err != nil {
			return nil, err
		}
		if options.finalizeNoop {
			if _, err := c.finalize(ctx, options.exportTemplate, options.graph); err != nil {
				return nil, err
			}
		} else {
			c.writeState()
		}
		return applyResultFromPlan(plan), nil
	}

	deployNodeNames := plan.deployNodeNames()
	if err := c.prepareApply(
		ctx,
		deployNodeNames,
		options.skipLabDirFileACLs,
		currentNodes,
	); err != nil {
		return nil, err
	}

	if err := c.deleteApplyEndpoints(ctx, plan); err != nil {
		return nil, err
	}

	if err := c.parkMigratedBridgeNSPorts(ctx, plan); err != nil {
		return nil, err
	}

	if err := c.parkRecreatedNodes(ctx, plan); err != nil {
		return nil, err
	}

	if err := c.deleteApplyNodes(ctx, plan); err != nil {
		return nil, err
	}

	if err := c.deployApplyNodes(ctx, plan, options.maxWorkers); err != nil {
		return nil, err
	}

	if err := c.restoreRecreatedNodes(ctx, plan); err != nil {
		return nil, err
	}

	if err := c.restoreMigratedBridgeNSPorts(ctx, plan); err != nil {
		return nil, err
	}

	if err := c.removeApplyLinkEndpoints(ctx, plan.addedLinks); err != nil {
		return nil, err
	}

	if err := c.deployLinks(ctx, plan.addedLinks, deployNodeNames); err != nil {
		return nil, err
	}

	if err := c.postDeployApplyNodes(ctx, deployNodeNames, options.skipPostDeploy); err != nil {
		return nil, err
	}

	if err := c.restartApplyNodes(ctx, plan.linkRestartNodeSet); err != nil {
		return nil, err
	}

	if err := c.updateRuntimeInfoForExistingNodes(ctx); err != nil {
		return nil, err
	}
	if err := c.syncTailscaleProxy(ctx); err != nil {
		return nil, err
	}
	if err := c.SyncMgmtHostRoutes(ctx); err != nil {
		return nil, err
	}

	if _, err := c.finalize(ctx, options.exportTemplate, options.graph); err != nil {
		return nil, err
	}

	return applyResultFromPlan(plan), nil
}

func (c *CLab) checkApplyTopologyDefinition(ctx context.Context) error {
	params := *clablinks.NewVerifyLinkParams()
	if len(c.Endpoints) > 0 {
		runtime := c.globalRuntime()
		if runtime == nil {
			return fmt.Errorf("container runtime is not initialized")
		}
		config := runtime.Config()
		if config.VerifyLinkParams != nil {
			params = *config.VerifyLinkParams
		}
	}
	params.AllowExistingEndpoint = true
	if err := c.verifyLinks(ctx, &params); err != nil {
		return err
	}

	if err := c.verifyRootNetNSLinks(); err != nil {
		return err
	}

	for _, nodeName := range sortedNodeNames(c.Nodes) {
		if err := c.Nodes[nodeName].CheckDeploymentConditions(ctx); err != nil {
			return err
		}
	}

	if err := c.verifyDuplicateAddresses(); err != nil {
		return err
	}

	return c.verifyTailscaleProxy()
}

func (c *CLab) prepareApply(
	ctx context.Context,
	addedNodes []string,
	skipLabDirFileACLs bool,
	currentNodes map[string]*runtimeNodeGroup,
) error {
	existing := c.collectExistingManagementAddresses(currentNodes)
	if err := c.prepareLabManagementNetwork(ctx, existing...); err != nil {
		return err
	}

	if err := c.prepareDeployArtifacts(ctx, skipLabDirFileACLs); err != nil {
		return err
	}

	for _, nodeName := range addedNodes {
		if err := c.Nodes[nodeName].PullImage(ctx); err != nil {
			return err
		}
	}

	return nil
}

func (c *CLab) removeApplyLinkEndpoints(ctx context.Context, links []clablinks.Link) error {
	for _, link := range links {
		for _, ep := range clablinks.RuntimeEndpoints(link) {
			node := ep.GetNode()

			// For BridgeNS bridge endpoints, use RemoveInterface instead of
			// RemoveOwnedInterface: bridge-attached interfaces are owned by the remote
			// endpoint, so per-node ownership checks would always fail.
			if node.GetLinkEndpointType() == clablinks.LinkEndpointTypeBridgeNS {
				parentNode, err := c.bridgeNSParentNode(node.GetShortName())
				if err != nil {
					return err
				}
				if err := clablinks.RemoveInterface(
					ctx,
					parentNode,
					ep.GetIfaceName(),
				); err != nil {
					return err
				}
				continue
			}

			if err := clablinks.RemoveOwnedInterface(
				ctx,
				node,
				ep.GetIfaceName(),
			); err != nil {
				return err
			}
		}
	}

	return nil
}

// try to preserve the existing addressing instead of reallocation.
func (c *CLab) collectExistingManagementAddresses(
	currentNodes map[string]*runtimeNodeGroup,
) []clabtypes.ExistingAddress {
	var existing []clabtypes.ExistingAddress
	for name, group := range currentNodes {
		for _, ctr := range group.containers {
			if c.mgmtNetByNetwork(ctr.NetworkName).Network != ctr.NetworkName {
				continue
			}
			for _, value := range []string{ctr.NetworkSettings.IPv4addr, ctr.NetworkSettings.IPv6addr} {
				if ip, err := netip.ParseAddr(value); err == nil {
					existing = append(
						existing,
						clabtypes.ExistingAddress{NodeName: name, ContainerID: ctr.ID, Address: ip},
					)
				}
			}
		}
	}
	return existing
}

