// ParkEndpoints moves all tracked endpoints into the node-owned parking namespace.
func (d *DefaultNode) ParkEndpoints(ctx context.Context) error {
	parkPath, err := clabutils.CreateOrGetNamedNetNS(d.parkingNetNSName())
	if err != nil {
		return fmt.Errorf("failed to create parking netns for node %q: %w", d.Cfg.ShortName, err)
	}
	// Reuse the parking node retained by a failed restore so it keeps the parked endpoints.
	parkingNode := d.parkingNode
	reused := parkingNode != nil
	if !reused {
		parkingNode = clablinks.NewParkingNode(d.Cfg.LongName, parkPath)
	}

	if err := parkingNode.CaptureFrom(ctx, d); err != nil {
		if !reused {
			_ = d.cleanupParkingNetNS()
		}
		return err
	}

	if err := parkingNode.RepointSymlink(); err != nil {
		repointErr := fmt.Errorf("failed to repoint symlink for node %q: %w", d.Cfg.ShortName, err)
		if _, restoreErr := parkingNode.RestoreTo(ctx, d); restoreErr != nil {
			// Keep the parking netns and its endpoints so a later restore can recover them.
			d.parkingNode = parkingNode
			return errors.Join(repointErr, restoreErr)
		}
		d.parkingNode = nil
		if cleanupErr := d.cleanupParkingNetNS(); cleanupErr != nil {
			return errors.Join(repointErr, cleanupErr)
		}
		return repointErr
	}
	d.parkingNode = parkingNode

	return nil
}

// RestoreEndpoints tries to get the parking node to unpark its interfaces.
func (d *DefaultNode) RestoreEndpoints(ctx context.Context) error {
	parkPath, err := d.parkingNetNSPath()
	if err != nil {
		// No parking netns means the node had no parked interfaces - e.g. it was
		// stopped outside of containerlab (so its interfaces were never parked) or
		// it has no dataplane links. Nothing to restore.
		d.parkingNode = nil
		log.Debugf("node %q has no parking netns, nothing to restore", d.Cfg.ShortName)
		return nil
	}
	parkingNode := d.parkingNode
	if parkingNode == nil {
		parkingNode = clablinks.NewParkingNode(d.Cfg.LongName, parkPath)
	}

	restored, err := parkingNode.RestoreTo(ctx, d)
	if err != nil {
		return err
	}

	for _, ep := range restored {
		log.Info("Restored link", "node", d.Cfg.ShortName, "interface", ep.GetIfaceName())
	}

	if err := d.cleanupParkingNetNS(); err != nil {
		return fmt.Errorf("failed to cleanup parking netns for node %q: %w", d.Cfg.ShortName, err)
	}
	d.parkingNode = nil

	return nil
}

func (d *DefaultNode) Stop(ctx context.Context) error {
	cfg := d.Config()

	if d.ShouldSkipLifecycle() {
		log.Debugf("node %q skips lifecycle stop", cfg.ShortName)
		return nil
	}

	status := d.OverwriteNode.GetContainerStatus(ctx)
	switch status {
	case clabruntime.Stopped:
		log.Debugf("node %q already stopped, skipping", cfg.ShortName)
		return nil
	case clabruntime.NotFound:
		return fmt.Errorf("node %q container %q not found", cfg.ShortName, cfg.LongName)
	}

