		if err := clablinks.RemoveOwnedInterface(ctx, ref.node, ref.key.iface); err != nil {
			if ref.bestEffort && errors.Is(err, clablinks.ErrInterfaceUnowned) {
				log.Debugf("skipping best-effort endpoint delete: %v", err)
				continue
			}
			return err
		}
	}

	return nil
}

