	if b.containerNs != "" {
		parentNode, err := b.resolveParentNode()
		if err != nil {
			return "", err
		}
		return parentNode.GetNSPath(ctx)
	}
	curns, err := ns.GetCurrentNS()
	if err != nil {
		return "", err
	}
	return curns.Path(), nil
}

