func (c *CLab) bridgeNSParentNode(bridgeName string) (clablinks.Node, error) {
	node, exists := c.Nodes[bridgeName]
	if !exists {
		return nil, fmt.Errorf("in-container bridge %q not found in topology", bridgeName)
